import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Reverse proxy and TLS","description":"Expose the client plane publicly; bind admin to loopback or a private network. Terminate TLS on the plane YAML or on the proxy.","frontmatter":{"title":"Reverse proxy and TLS","description":"Expose the client plane publicly; bind admin to loopback or a private network. Terminate TLS on the plane YAML or on the proxy."},"headers":[],"relativePath":"en/guide/config/reverse-proxy.md","filePath":"en/guide/config/reverse-proxy.md","lastUpdated":1790057721000}`),a={name:`en/guide/config/reverse-proxy.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="reverse-proxy-and-tls" tabindex="-1">Reverse proxy and TLS <a class="header-anchor" href="#reverse-proxy-and-tls" aria-label="Permalink to “Reverse proxy and TLS”">​</a></h1><p>Publish only the client plane (<code>:8080</code>) on the internet. Bind the admin plane to <code>127.0.0.1</code> or a private network, then reach it over VPN / SSH / an internal proxy.</p><p>TLS options (mixable per plane):</p><ol><li>Plane YAML <code>tls_cert</code> + <code>tls_key</code> (both non-empty).</li><li>Proxy terminates TLS; then that plane must list <code>trusted_proxies</code> or <code>X-Forwarded-For</code> is ignored.</li></ol><p>Empty <code>trusted_proxies</code> calls <code>SetTrustedProxies(nil)</code> — <strong>not</strong> Gin’s default trust-all.</p><p>Production admin reverse-proxies <code>/api/v1/projects/**</code> to this process’s client plane for console previews. Admin <code>GET /</code> serves the console SPA; host the docs site separately so it does not collide with the SPA.</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};